package main
import("strings";"strconv")
var _=strings.Compare
var _=strconv.Itoa
func solve(x map[string]any) any {p:=x["pointer"].(string);var cur any=x["doc"];if p==""{return cur};if !strings.HasPrefix(p,"/"){return nil};for _,raw:=range strings.Split(p[1:],"/"){key:="";for i:=0;i<len(raw);i++{if raw[i]=='~'{i++;if i>=len(raw)||(raw[i]!='0'&&raw[i]!='1'){return nil};if raw[i]=='0'{key+="~"}else{key+="/"}}else{key+=string(raw[i])}};switch node:=cur.(type){case map[string]any:var ok bool;cur,ok=node[key];if !ok{return nil};case []any:n,err:=strconv.Atoi(key);if err!=nil||strconv.Itoa(n)!=key||n<0||n>=len(node){return nil};cur=node[n];default:return nil}};return cur}

