package main
import("encoding/json";"testing";"reflect")
func TestContractBoundaries(t *testing.T){var rows [][]json.RawMessage;if e:=json.Unmarshal([]byte(`[[{"doc": [5, 7], "pointer": "/1"}, 7], [{"doc": {"a/b": {"~": 9}}, "pointer": "/a~1b/~0"}, 9], [{"doc": ["a"], "pointer": "/00"}, null], [{"doc": {"~2": 1}, "pointer": "/~2"}, null], [{"doc": "root", "pointer": ""}, "root"]]`),&rows);e!=nil{t.Fatal(e)};for _,row:=range rows{var input map[string]any;var expected,actual any;json.Unmarshal(row[0],&input);json.Unmarshal(row[1],&expected);b,e:=json.Marshal(solve(input));if e!=nil{t.Fatal(e)};json.Unmarshal(b,&actual);if !reflect.DeepEqual(actual,expected){t.Fatalf("got %v expected %v",actual,expected)}}}
